public class TenantResolutionMiddleware
{
    private readonly RequestDelegate _next;
    private readonly ITenantRepository _tenantRepo;

    public TenantResolutionMiddleware(RequestDelegate next, ITenantRepository tenantRepo)
    {
        _next = next;
        _tenantRepo = tenantRepo;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        var host = context.Request.Host.Host;
        var subdomain = host.Split('.').FirstOrDefault();

        if (!string.IsNullOrEmpty(subdomain))
        {
            var tenant = await _tenantRepo.GetBySubdomainAsync(subdomain);
            if (tenant != null)
            {
                context.Items["TenantId"] = tenant.Id;
                context.Items["IdpEntityId"] = tenant.IdpEntityId;
                context.Items["IdpMetadataUrl"] = tenant.IdpMetadataUrl;
            }
        }

        await _next(context);
    }
}

public async Task<User> HandleFederatedLoginAsync(
    string tenantId, 
    ClaimsPrincipal principal)
{
    var email = principal.FindFirst(ClaimTypes.Email)?.Value 
             ?? principal.FindFirst("email")?.Value;

    if (string.IsNullOrEmpty(email))
        throw new InvalidOperationException("Email claim is required.");

    var user = await _userRepo.GetByEmailAsync(email);

    if (user == null)
    {
        user = new User
        {
            Id = Guid.NewGuid().ToString(),
            Email = email,
            DisplayName = principal.Identity.Name,
            TenantId = tenantId,
            IdentityProvider = principal.FindFirst("idp")?.Value ?? "saml",
            CreatedAt = DateTime.UtcNow
        };

        // Map tenant-specific roles
        var groups = principal.FindAll("groups").Select(c => c.Value).ToList();
        user.Roles = MapGroupsToRoles(tenantId, groups);

        await _userRepo.CreateAsync(user);
    }
    else if (user.TenantId != tenantId)
    {
        throw new InvalidOperationException("User does not belong to this tenant.");
    }

    return user;
}

